// Shared type definitions for the Task Management API

// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Event Bus Contract
// ============================================================

export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
}

import { IEventBus } from "./types";

export class EventBus implements IEventBus {
  private subscribers: Map<string, Array<(payload: unknown) => void>> = new Map();

  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event) || [];
    // Dispatch synchronously in order of subscription
    for (const cb of callbacks) {
      try {
        cb(payload);
      } catch (err) {
        // Swallow to avoid one bad subscriber breaking others
        // In a real system, we'd log this
      }
    }
  }

  subscribe(event: string, callback: (payload: unknown) => void): void {
    const list = this.subscribers.get(event) || [];
    list.push(callback);
    this.subscribers.set(event, list);
  }
}

export default EventBus;

import { IUserService, User } from "../types";
import { randomUUID } from "crypto";

export class UserService implements IUserService {
  // Exclusive data ownership
  private users: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const id = randomUUID();
    const user: User = { id, name: input.name, email: input.email };
    this.users.set(id, user);
    return user;
  }

  getById(id: string): User {
    const u = this.users.get(id);
    if (!u) throw new Error(`User not found: ${id}`);
    return u;
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const u = this.getById(id);
    const updated: User = { ...u, ...input } as User;
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.users.delete(id)) {
      throw new Error(`User not found: ${id}`);
    }
  }
}

export default UserService;

import { IProjectService, Project } from "../types";
import { randomUUID } from "crypto";

export class ProjectService implements IProjectService {
  // Exclusive data ownership
  private projects: Map<string, Project> = new Map();

  create(input: { name: string; description: string }): Project {
    const id = randomUUID();
    const project: Project = { id, name: input.name, description: input.description, memberIds: [] };
    this.projects.set(id, project);
    return project;
  }

  getById(id: string): Project {
    const p = this.projects.get(id);
    if (!p) throw new Error(`Project not found: ${id}`);
    return p;
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, input: Partial<{ name: string; description: string }>): Project {
    const p = this.getById(id);
    const updated: Project = { ...p, ...input } as Project;
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.projects.delete(id)) {
      throw new Error(`Project not found: ${id}`);
    }
  }

  addMember(projectId: string, userId: string): Project {
    const p = this.getById(projectId);
    if (!p.memberIds.includes(userId)) {
      p.memberIds.push(userId);
    }
    this.projects.set(projectId, p);
    return p;
  }

  removeMember(projectId: string, userId: string): Project {
    const p = this.getById(projectId);
    p.memberIds = p.memberIds.filter((id) => id !== userId);
    this.projects.set(projectId, p);
    return p;
  }
}

export default ProjectService;

import { IEventBus, ITaskService, Task, TaskAssignedPayload, TaskStatus, TaskStatusChangedPayload } from "../types";
import { randomUUID } from "crypto";

export class TaskService implements ITaskService {
  private tasks: Map<string, Task> = new Map();

  constructor(private eventBus: IEventBus) {}

  create(input: { title: string; description: string; projectId: string }): Task {
    const id = randomUUID();
    const task: Task = {
      id,
      title: input.title,
      description: input.description,
      status: "todo",
      assigneeId: null,
      projectId: input.projectId,
    };
    this.tasks.set(id, task);
    return task;
  }

  getById(id: string): Task {
    const t = this.tasks.get(id);
    if (!t) throw new Error(`Task not found: ${id}`);
    return t;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter((t) => t.projectId === projectId);
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const t = this.getById(id);
    const updated: Task = { ...t, ...input } as Task;
    this.tasks.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.tasks.delete(id)) {
      throw new Error(`Task not found: ${id}`);
    }
  }

  assign(taskId: string, assigneeId: string): Task {
    const t = this.getById(taskId);
    t.assigneeId = assigneeId;
    this.tasks.set(taskId, t);
    const payload: TaskAssignedPayload = { taskId: t.id, taskTitle: t.title, assigneeId };
    this.eventBus.publish("task.assigned", payload);
    return t;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const t = this.getById(taskId);
    const oldStatus = t.status;

    // Enforce forward-only state transitions
    if (oldStatus === newStatus) return t;

    const order: TaskStatus[] = ["todo", "in-progress", "done"];
    const oldIndex = order.indexOf(oldStatus);
    const newIndex = order.indexOf(newStatus);

    if (newIndex === -1) throw new Error(`Invalid status: ${newStatus}`);

    if (newIndex !== oldIndex + 1) {
      // Prevent backwards or skipping transitions
      throw new Error(`Invalid status transition: ${oldStatus} -> ${newStatus}`);
    }

    t.status = newStatus;
    this.tasks.set(taskId, t);

    const payload: TaskStatusChangedPayload = {
      taskId: t.id,
      taskTitle: t.title,
      assigneeId: t.assigneeId,
      oldStatus,
      newStatus,
    };
    this.eventBus.publish("task.statusChanged", payload);

    return t;
  }
}

export default TaskService;

import { ICommentService, IEventBus, Comment, CommentAddedPayload } from "../types";
import { randomUUID } from "crypto";

export class CommentService implements ICommentService {
  private comments: Map<string, Comment> = new Map();

  constructor(private eventBus: IEventBus) {}

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const comment: Comment = {
      id,
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt,
    };
    this.comments.set(id, comment);

    const payload: CommentAddedPayload = {
      commentId: id,
      taskId: input.taskId,
      taskTitle: "", // Filled by router/main using domain knowledge? But per contract, CommentService publishes. We'll allow empty title if unknown.
      authorId: input.authorId,
      authorName: "",
    };
    // We publish with minimal info; consumers may need to resolve names. For demo, router may enrich before calling create.
    this.eventBus.publish("comment.added", payload);

    return comment;
  }

  getById(id: string): Comment {
    const c = this.comments.get(id);
    if (!c) throw new Error(`Comment not found: ${id}`);
    return c;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter((c) => c.taskId === taskId);
  }

  delete(id: string): void {
    if (!this.comments.delete(id)) {
      throw new Error(`Comment not found: ${id}`);
    }
  }
}

export default CommentService;

import {
  INotificationService,
  Notification,
  TaskAssignedPayload,
  TaskStatusChangedPayload,
  CommentAddedPayload,
} from "../types";
import { randomUUID } from "crypto";

export class NotificationService implements INotificationService {
  // Exclusive data ownership
  private notifications: Map<string, Notification> = new Map();

  // Projection of task state we care about for notifications
  private taskInfo: Map<string, { title: string; assigneeId: string | null }> = new Map();

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter((n) => n.userId === userId);
  }

  markAsRead(notificationId: string): Notification {
    const n = this.notifications.get(notificationId);
    if (!n) throw new Error(`Notification not found: ${notificationId}`);
    if (!n.read) {
      n.read = true;
      this.notifications.set(notificationId, n);
    }
    return n;
  }

  // Event handlers to be wired in main.ts
  handleTaskAssigned = (payload: TaskAssignedPayload): void => {
    this.taskInfo.set(payload.taskId, { title: payload.taskTitle, assigneeId: payload.assigneeId });
    this.createNotification(payload.assigneeId, `Task '${payload.taskTitle}' assigned to you`);
  };

  handleTaskStatusChanged = (payload: TaskStatusChangedPayload): void => {
    this.taskInfo.set(payload.taskId, { title: payload.taskTitle, assigneeId: payload.assigneeId });
    if (payload.assigneeId) {
      this.createNotification(
        payload.assigneeId,
        `Task '${payload.taskTitle}' status changed to ${payload.newStatus}`
      );
    }
  };

  handleCommentAdded = (payload: CommentAddedPayload): void => {
    const info = this.taskInfo.get(payload.taskId);
    const title = payload.taskTitle || (info ? info.title : "");
    const assigneeId = info ? info.assigneeId : null;
    if (assigneeId) {
      const authorPart = payload.authorName ? ` by ${payload.authorName}` : "";
      const titlePart = title ? ` '${title}'` : "";
      this.createNotification(assigneeId, `New comment on task${titlePart}${authorPart}`);
    }
  };

  // Internal helper
  private createNotification(userId: string, message: string): Notification {
    const id = randomUUID();
    const n: Notification = {
      id,
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.notifications.set(id, n);
    return n;
  }
}

export default NotificationService;

import { createServer, IncomingMessage, ServerResponse } from "http";
import { URL } from "url";
import {
  IUserService,
  IProjectService,
  ITaskService,
  ICommentService,
  INotificationService,
  Task,
  Comment,
  Notification,
} from "./types";

export interface RouterDeps {
  userService: IUserService;
  projectService: IProjectService;
  taskService: ITaskService;
  commentService: ICommentService;
  notificationService: INotificationService;
}

export function startServer(port: number, deps: RouterDeps) {
  const server = createServer(async (req: IncomingMessage, res: ServerResponse) => {
    // Basic CORS and JSON headers
    res.setHeader("Content-Type", "application/json");
    res.setHeader("Access-Control-Allow-Origin", "*");
    res.setHeader("Access-Control-Allow-Methods", "GET,POST,PUT,DELETE,OPTIONS");
    res.setHeader("Access-Control-Allow-Headers", "Content-Type");
    if (req.method === "OPTIONS") {
      res.writeHead(200);
      res.end();
      return;
    }

    const url = new URL(req.url || "", `http://${req.headers.host}`);

    try {
      const { method } = req;
      const path = url.pathname;
      const send = (code: number, body: unknown) => {
        res.statusCode = code;
        res.end(JSON.stringify(body));
      };

      // Helper to read JSON body
      const readBody = async <T>(): Promise<T> => {
        return new Promise((resolve, reject) => {
          let data = "";
          req.on("data", (chunk) => (data += chunk));
          req.on("end", () => {
            try {
              resolve(data ? JSON.parse(data) : {});
            } catch (err) {
              reject(new Error("Invalid JSON"));
            }
          });
          req.on("error", reject);
        });
      };

      // Users
      if (method === "GET" && path === "/users") {
        return send(200, deps.userService.getAll());
      }
      if (method === "POST" && path === "/users") {
        const body = await readBody<{ name: string; email: string }>();
        const u = deps.userService.create(body);
        return send(201, u);
      }
      if (method === "GET" && path.startsWith("/users/")) {
        const id = path.split("/")[2];
        return send(200, deps.userService.getById(id));
      }
      if (method === "PUT" && path.startsWith("/users/")) {
        const id = path.split("/")[2];
        const body = await readBody<Partial<{ name: string; email: string }>>();
        return send(200, deps.userService.update(id, body));
      }
      if (method === "DELETE" && path.startsWith("/users/")) {
        const id = path.split("/")[2];
        deps.userService.delete(id);
        return send(204, {});
      }

      // Projects
      if (method === "GET" && path === "/projects") {
        return send(200, deps.projectService.getAll());
      }
      if (method === "POST" && path === "/projects") {
        const body = await readBody<{ name: string; description: string }>();
        return send(201, deps.projectService.create(body));
      }
      if (method === "GET" && path.startsWith("/projects/") && !path.endsWith("/members")) {
        const id = path.split("/")[2];
        return send(200, deps.projectService.getById(id));
      }
      if (method === "PUT" && path.startsWith("/projects/") && !path.endsWith("/members")) {
        const id = path.split("/")[2];
        const body = await readBody<Partial<{ name: string; description: string }>>();
        return send(200, deps.projectService.update(id, body));
      }
      if (method === "DELETE" && path.startsWith("/projects/") && !path.endsWith("/members")) {
        const id = path.split("/")[2];
        deps.projectService.delete(id);
        return send(204, {});
      }
      if (method === "POST" && path.endsWith("/members")) {
        const id = path.split("/")[2];
        const body = await readBody<{ userId: string }>();
        return send(200, deps.projectService.addMember(id, body.userId));
      }
      if (method === "DELETE" && path.endsWith("/members")) {
        const id = path.split("/")[2];
        const body = await readBody<{ userId: string }>();
        return send(200, deps.projectService.removeMember(id, body.userId));
      }

      // Tasks
      if (method === "GET" && path === "/tasks") {
        const projectId = url.searchParams.get("projectId");
        if (!projectId) throw new Error("projectId query param is required");
        return send(200, deps.taskService.getByProject(projectId));
      }
      if (method === "POST" && path === "/tasks") {
        const body = await readBody<{ title: string; description: string; projectId: string }>();
        return send(201, deps.taskService.create(body));
      }
      if (method === "GET" && path.startsWith("/tasks/")) {
        const id = path.split("/")[2];
        return send(200, deps.taskService.getById(id));
      }
      if (method === "PUT" && path.startsWith("/tasks/") && !path.endsWith("/status") && !path.endsWith("/assign")) {
        const id = path.split("/")[2];
        const body = await readBody<Partial<{ title: string; description: string }>>();
        return send(200, deps.taskService.update(id, body));
      }
      if (method === "DELETE" && path.startsWith("/tasks/") && !path.endsWith("/status") && !path.endsWith("/assign")) {
        const id = path.split("/")[2];
        deps.taskService.delete(id);
        return send(204, {});
      }
      if (method === "PUT" && path.endsWith("/status")) {
        const id = path.split("/")[2];
        const body = await readBody<{ status: Task["status"] }>();
        return send(200, deps.taskService.changeStatus(id, body.status));
      }
      if (method === "PUT" && path.endsWith("/assign")) {
        const id = path.split("/")[2];
        const body = await readBody<{ assigneeId: string }>();
        return send(200, deps.taskService.assign(id, body.assigneeId));
      }

      // Comments
      if (method === "GET" && path === "/comments") {
        const taskId = url.searchParams.get("taskId");
        if (!taskId) throw new Error("taskId query param is required");
        return send(200, deps.commentService.getByTask(taskId));
      }
      if (method === "POST" && path === "/comments") {
        const body = await readBody<{ taskId: string; authorId: string; body: string }>();
        const c = deps.commentService.create(body);
        // enhancement: we could enrich event payloads elsewhere
        return send(201, c);
      }
      if (method === "GET" && path.startsWith("/comments/")) {
        const id = path.split("/")[2];
        return send(200, deps.commentService.getById(id));
      }
      if (method === "DELETE" && path.startsWith("/comments/")) {
        const id = path.split("/")[2];
        deps.commentService.delete(id);
        return send(204, {});
      }

      // Notifications
      if (method === "GET" && path === "/notifications") {
        const userId = url.searchParams.get("userId");
        if (!userId) throw new Error("userId query param is required");
        return send(200, deps.notificationService.getByUser(userId));
      }
      if (method === "PUT" && path.startsWith("/notifications/") && path.endsWith("/read")) {
        const id = path.split("/")[2];
        return send(200, deps.notificationService.markAsRead(id));
      }

      // Fallback
      send(404, { error: "Not found" });
    } catch (err: any) {
      res.statusCode = 400;
      res.end(JSON.stringify({ error: err.message || String(err) }));
    }
  });

  server.listen(port);
  return server;
}

import EventBus from "./event-bus";
import UserService from "./services/user-service";
import ProjectService from "./services/project-service";
import TaskService from "./services/task-service";
import CommentService from "./services/comment-service";
import NotificationService from "./services/notification-service";
import { startServer } from "./router";

const port = 3000;

// Wire up services and event bus
const eventBus = new EventBus();

const userService = new UserService();
const projectService = new ProjectService();
const taskService = new TaskService(eventBus);
const commentService = new CommentService(eventBus);
const notificationService = new NotificationService();

// Event subscriptions
// TaskService publishes
eventBus.subscribe("task.assigned", (payload) => {
  notificationService.handleTaskAssigned(payload as any);
});

eventBus.subscribe("task.statusChanged", (payload) => {
  notificationService.handleTaskStatusChanged(payload as any);
});

// CommentService publishes
// For better messages, we enrich CommentAddedPayload with task title and author name if possible
import { IEventBus, CommentAddedPayload } from "./types";

const enrichCommentPayload = (payload: CommentAddedPayload): CommentAddedPayload => {
  try {
    const task = taskService.getById(payload.taskId);
    const author = userService.getById(payload.authorId);
    return { ...payload, taskTitle: task.title, authorName: author.name };
  } catch {
    return payload;
  }
};

(eventBus as IEventBus).subscribe("comment.added", (raw) => {
  const p = enrichCommentPayload(raw as CommentAddedPayload);
  notificationService.handleCommentAdded(p);
});

startServer(port, {
  userService,
  projectService,
  taskService,
  commentService,
  notificationService,
});

console.log(`Server started on http://localhost:${port}`);

import http from "http";
import { startServer } from "./router";
import EventBus from "./event-bus";
import UserService from "./services/user-service";
import ProjectService from "./services/project-service";
import TaskService from "./services/task-service";
